var n=`0808-nshima`;var t=`world-0808`;var s=`ZM`;var a=`eastern-africa`;var r=4;var o=36;var l={en:`Nshima`,ua:`Ншіма`};var m={en:`Nshima is a Zambia dish made with cornmeal. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Ншіма, страва кухні країни Замбія. Основні складники: кукурудзяна крупа дрібного помелу. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var g=[{en:`Cook the listed ingredients in simmering water for about 8 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 8 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:8,i:[[`water`,900,`ml`],[`table-salt`,5,`g`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 20 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 20 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:20,i:[[`cornmeal`,420,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`unsalted-butter`,20,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`unsalted-butter`,20,`g`]]}];var d={slug:n,id:t,country:`ZM`,region:a,servings:4,minutes:36,title:l,text:m,steps:g};export{s as country,d as default,t as id,o as minutes,a as region,r as servings,n as slug,g as steps,m as text,l as title};